/*
 Theme Name:   Astra Child
 Description: Child theme of Astra
 Author:       Sajesh Khadgi
 Template:     astra
 Version:      1.0.0
*/

@import url("../astra/style.css");

/*
 * Flat, borderless form fields, site-wide.
 *
 * Why an override instead of an edit: these rules are compiled into Astra's
 * minified bundles (assets/css/minified/*.min.css, line 3, single-line files)
 * and the focus rule is additionally generated at runtime in
 * inc/class-astra-dynamic-css.php:986-1000 and printed inline in wp_head.
 * Neither is cleanly editable in place, and the theme updates overwrite them.
 *
 * Two things make these rules win:
 *
 * 1. Specificity. The inline <style> prints late, after the child stylesheet
 *    is enqueued, so at equal specificity it would win on source order. The
 *    "html body " prefix adds two element selectors, which beats every
 *    original selector including the ID-based ones (#ast-scroll-top,
 *    #coupon_code, #ast-coupon-code).
 * 2. Source order within this file. These rules must stay below the @import
 *    above.
 */

/* Base state. Selectors merged from the two original blocks: the first covered
   email/password/search/tel/text/url/textarea, the second added number, reset
   and select. */
html body input[type="email"],
html body input[type="number"],
html body input[type="password"],
html body input[type="reset"],
html body input[type="search"],
html body input[type="tel"],
html body input[type="text"],
html body input[type="url"],
html body select,
html body textarea {
  color: #666;
  padding: 0.75em;
  height: auto;
  border-width: 0;
  border-style: none;
  border-radius: 0;
  background: var(--ast-comment-inputs-background, #fafafa);
  box-shadow: none;
  box-sizing: border-box;
  transition: all 0.2s linear;
}

/* -webkit-appearance: none is deliberately NOT applied to select: it removes the
   dropdown arrow, which is the only affordance telling a keyboard user the
   control opens a list. */
html body input[type="email"],
html body input[type="number"],
html body input[type="password"],
html body input[type="reset"],
html body input[type="search"],
html body input[type="tel"],
html body input[type="text"],
html body input[type="url"],
html body textarea {
  -webkit-appearance: none;
  appearance: none;
}

/* Focus state. The transparent 0-width border is carried over from the original
   block, but a box-shadow ring is kept: Astra sets `input { outline: none }` in
   its dynamic CSS, so with no border and no outline there would be no visible
   focus indicator at all, failing WCAG 2.4.7 (Focus Visible). A shadow does not
   affect layout, so nothing shifts on focus.

   background is intentionally absent here. It is not re-applied to the three
   non-input selectors in this list (#ast-scroll-top, .menu-toggle-close,
   .ast-mobile-menu-trigger-minimal), which are styled controls and links whose
   own backgrounds must not be flattened to the comment-field colour. The base
   rule above already covers the real form fields. */
html body input:focus,
html body input[type="text"]:focus,
html body input[type="email"]:focus,
html body input[type="url"]:focus,
html body input[type="password"]:focus,
html body input[type="reset"]:focus,
html body input[type="search"]:focus,
html body input[type="number"]:focus,
html body select:focus,
html body textarea:focus,
html body .wp-block-search__input:focus,
html body [data-section="section-header-mobile-trigger"] .ast-button-wrap .ast-mobile-menu-trigger-minimal:focus,
html body .ast-mobile-popup-drawer.active .menu-toggle-close:focus,
html body #ast-scroll-top:focus,
html body #coupon_code:focus,
html body #ast-coupon-code:focus {
  border-style: none;
  border-color: transparent;
  border-width: 0;
  box-shadow: 0 0 0 2px var(--ast-global-color-primary, #2563eb);
  outline: 2px solid transparent;
  outline-offset: 2px;
}
